mapper.select:
SELECT
(SELECT COUNT(*) FROM assignments a JOIN course_offerings o ON o.id=a.offering_id JOIN offering_members m ON m.offering_id=a.offering_id WHERE m.user_id=#{studentId} AND m.role='student' AND m.status='active' AND a.status IN ('published','archived')
AND a.offering_id=#{offeringId}
AND o.term_id=#{termId}) AS all_count,
(SELECT COUNT(*) FROM assignments a JOIN course_offerings o ON o.id=a.offering_id JOIN offering_members m ON m.offering_id=a.offering_id LEFT JOIN submissions s ON s.assignment_id=a.id AND s.student_id=#{studentId} AND s.is_current=1 WHERE m.user_id=#{studentId} AND m.role='student' AND m.status='active' AND a.status IN ('published','archived') AND s.id IS NULL
AND a.offering_id=#{offeringId}
AND o.term_id=#{termId}) AS todo_count,
(SELECT COUNT(*) FROM assignments a JOIN course_offerings o ON o.id=a.offering_id JOIN offering_members m ON m.offering_id=a.offering_id LEFT JOIN submissions s ON s.assignment_id=a.id AND s.student_id=#{studentId} AND s.is_current=1 WHERE m.user_id=#{studentId} AND m.role='student' AND m.status='active' AND a.status IN ('published','archived') AND s.id IS NOT NULL
AND a.offering_id=#{offeringId}
AND o.term_id=#{termId}) AS done_count,
(SELECT COUNT(*) FROM assignments a JOIN course_offerings o ON o.id=a.offering_id JOIN offering_members m ON m.offering_id=a.offering_id LEFT JOIN submissions s ON s.assignment_id=a.id AND s.student_id=#{studentId} AND s.is_current=1 WHERE m.user_id=#{studentId} AND m.role='student' AND m.status='active' AND a.status='archived' AND s.id IS NULL
AND a.offering_id=#{offeringId}
AND o.term_id=#{termId}) AS archived_incomplete_count

SELECT id,assignment_id,offering_id,attempt_no AS attempt_number,workspace_revision,submitted_at,is_late AS late,CASE WHEN is_current=0 THEN 1 ELSE 0 END AS superseded,'none' AS feedback_status
FROM submissions WHERE assignment_id=#{assignmentId} AND student_id=#{studentId}
ORDER BY attempt_no DESC LIMIT #{size} OFFSET #{offset}

SELECT a.chapter_id,a.title,a.type,a.is_required,a.description,a.estimated_minutes,a.due_at,a.late_until,a.allow_resubmit,a.max_attempts,a.max_score,a.current_ai_policy_id AS ai_policy_version,a.id,a.offering_id,a.status AS publication_state,a.published_at,
(SELECT COUNT(DISTINCT s.student_id) FROM submissions s WHERE s.assignment_id=a.id) AS submitted_student_count,
0 AS pending_review_count
FROM assignments a WHERE a.offering_id=#{offeringId}
AND a.status=#{publicationState}
ORDER BY a.created_at DESC,a.id DESC LIMIT #{size} OFFSET #{offset}
